	'h_fe' => 'Tarifs,|noir sur blanc.',
	'h_fv' => 'Une première consultation|est avant tout un échange.',
	'h_im' => 'Un traitement progressif,|choisi avec soin.',
	'h_nl' => 'La lettre des pollens,|quatre fois par an.',
	'h_pr' => 'Politique de confidentialité',
